{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C04","C14","C15","C25","C28","C30","C31","C33","C38","C47","C56","C53"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C04","C14","C15","C25","C28","C30","C31","C33","C38","C47","C56","C53"],
  "claims": [
    {
      "claim": "Direct absolute oral bioavailability values for piperazine/heteroaromatic comparators are above the 20% threshold: GSK1322322 77% fed and 57% fasted (C04, C15), brigatinib 46% (C14), and the piperazine-containing TDP223206 rat F 24.46% at 50 mg/kg and 32.95% at 10 mg/kg (C25, C28).",
      "card_ids": ["C04","C14","C15","C25","C28"]
    },
    {
      "claim": "The close structural analog SHR6390 shows measurable oral systemic exposure after single 150 mg doses: fasted geometric-mean Cmax 52.2 ng/mL (C38), fed Cmax 81.8 ng/mL (C33), monotherapy AUC0-inf 2140 h·ng/mL (C30), and [14C] Cmax 42.9 ng eq/mL (C31), supporting oral absorption.",
      "card_ids": ["C30","C31","C33","C38"]
    },
    {
      "claim": "Same-class ribociclib shows high Caco-2 absorptive permeability (Papp A→B 135 nm/s) with a low efflux ratio of 1.3, supporting adequate intestinal absorption for the piperazine/cyclopentyl CDK4/6 chemotype.",
      "card_ids": ["C56"]
    },
    {
      "claim": "A piperazine/cyclopentyl-containing compound (M06) shows high Caco-2 absorptive permeability (Papp A→B 32.74 x10^-6 cm/s) with only moderate efflux (ER 1.9), further supporting absorption for this structural class.",
      "card_ids": ["C53"]
    },
    {
      "claim": "Ribociclib succinate solubility of 0.8 mg/mL at pH 6.8 (C47) indicates adequate aqueous solubility for a moderate-dose oral CDK4/6 inhibitor; no affirmative threshold-relevant evidence supports F < 20%.",
      "card_ids": ["C47"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C56","C64","C53","C62","C63"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is present.",
    "No IV/oral AUC comparison is available for the query or close analogs; L3 AUC/Cmax records lack an IV comparator and cannot directly establish F >= 20%.",
    "No query-specific gut-wall efflux or intestinal metabolism experiments are supplied; L5 records are for analogs or other chemotypes.",
    "L5 efflux/first-pass records for ciprofloxacin (C55, C57), NDI (C54), sarafloxacin (C61), and CMDCK (C59) are low-transferability to the query and do not establish F < 20%.",
    "Ciprofloxacin and norfloxacin solubility records (C41-C46, C48-C52) are not applicable to the query chemotype.",
    "The physicochemical prior (low neutral fraction, high TPSA/HBA) predicts absorption liability, but experimental analog evidence outweighs it; residual uncertainty is reflected in moderate confidence."
  ],
  "decision_summary": "Predicted high: F >= 20% is better supported. Direct absolute-F values above threshold for piperazine/heteroaromatic comparators (46-77%), rat F >20% for a piperazine analog, measurable oral exposure for the close analog SHR6390, adequate ribociclib solubility, and L5 Caco-2 permeability/efflux data for same-class ribociclib and a piperazine/cyclopentyl compound support adequate oral absorption. No affirmative threshold-relevant evidence supports F < 20%; L5 efflux/first-pass records for other chemotypes are low-transferability."
}

